mapper.select:
 SELECT c.*,
(SELECT u.user_name from sys_user u where u.user_id = c.manager_accounting_user_id ) manager_accounting ,
(SELECT u.user_name from sys_user u where u.user_id = c.bookkeeping_accounting_user_id ) bookkeeping_accounting ,
(SELECT u.user_name from sys_user u where u.user_id = c.assistant_accounting_user_id ) assistant_accounting
FROM t_account_book c where c.is_del = 0 and c.status = 0

    and c.server_status = #{serverStatus}


    and c.customer_name like CONCAT('%',#{customerName},'%')


    and c.vat_type = #{vatType}


    and date_format(c.create_period,'%Y-%m') = date_format(#{createPeriod},'%Y-%m')


    and c.current_period = #{currentPeriod}


    and (c.bookkeeping_accounting_user_id = #{bookkeepingAccountingUserId} or c.assistant_accounting_user_id = #{bookkeepingAccountingUserId})


    and c.dept_id = #{deptId}

order by create_time DESC

SELECT count( book.book_id ) amount, sum( CASE WHEN book.book_count = 0 THEN 1 ELSE 0 END ) unfinished, ( SELECT COUNT( col.id ) FROM t_collection col WHERE col.service_class_id = 1 AND col.is_del = 0 AND col.is_end = 0
AND col.dept_id = #{deptId}
AND DATE_FORMAT( col.create_time, '%Y%m' ) = DATE_FORMAT( CURDATE( ), '%Y%m' )
) uncleared FROM t_account_book book
is_del = 0
AND book.dept_id = #{deptId}
AND DATE_FORMAT( book.create_time, '%Y%m' ) = DATE_FORMAT( CURDATE( ), '%Y%m' )
